import{_ as e,o as s,c as l,a2 as n}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"L1 指南：看门狗与健康监控","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/watchdog-health.md","filePath":"zh/l1/watchdog-health.md"}'),t={name:"zh/l1/watchdog-health.md"};function o(p,a,c,h,i,r){return s(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="l1-指南-看门狗与健康监控" tabindex="-1">L1 指南：看门狗与健康监控 <a class="header-anchor" href="#l1-指南-看门狗与健康监控" aria-label="Permalink to &quot;L1 指南：看门狗与健康监控&quot;">​</a></h1><h2 id="看门狗-kernel-core-core-watchdog-h-18-个声明-编号-5" tabindex="-1">看门狗 - <code>kernel/core/core_watchdog.h</code>（18 个声明；编号 5） <a class="header-anchor" href="#看门狗-kernel-core-core-watchdog-h-18-个声明-编号-5" aria-label="Permalink to &quot;看门狗 - \`kernel/core/core_watchdog.h\`（18 个声明；编号 5）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>watchdog_register(name, timeout_ms, policy)  -&gt; slot</span></span>
<span class="line"><span>watchdog_start(slot)</span></span>
<span class="line"><span>watchdog_feed(slot)</span></span>
<span class="line"><span>watchdog_stop(slot)</span></span>
<span class="line"><span>watchdog_set_timeout(slot, ms)</span></span></code></pre></div><p>已注册的槽位是一个策略看门狗：任务必须喂狗； 超时会杀死任务（原因已记录），而内核继续运行。 硬件看门狗（Intel TCO、ACPI WDAT）位于其下层并 重置整台机器 - 端到端测试套件通过真实重置和二次启动 证明了这一点。</p><h2 id="健康-kernel-core-core-health-h-8-个声明-编号-5" tabindex="-1">健康 - <code>kernel/core/core_health.h</code>（8 个声明；编号 5） <a class="header-anchor" href="#健康-kernel-core-core-health-h-8-个声明-编号-5" aria-label="Permalink to &quot;健康 - \`kernel/core/core_health.h\`（8 个声明；编号 5）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>health_get_cpu(out)</span></span>
<span class="line"><span>health_get_mem(out)</span></span>
<span class="line"><span>health_get_tasks(out)</span></span>
<span class="line"><span>health_get_io(out)</span></span>
<span class="line"><span>health_export(path)          // valid JSON to /var/log/health.json</span></span></code></pre></div><p>阈值会向内核日志发出警报（在锁定的核心上触发 <code>CPU-LOCKED</code>...）； <code>health</code>、<code>health watch</code>、<code>health export</code> 是相关命令； 端到端测试验证了警报线路和 JSON 有效性。</p><h2 id="klog-kernel-lib-lib-klog-h-29-个声明-编号-6" tabindex="-1">klog - <code>kernel/lib/lib_klog.h</code>（29 个声明；编号 6） <a class="header-anchor" href="#klog-kernel-lib-lib-klog-h-29-个声明-编号-6" aria-label="Permalink to &quot;klog - \`kernel/lib/lib_klog.h\`（29 个声明；编号 6）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>klog_write(level, fmt, ...)</span></span>
<span class="line"><span>klog_set_level(lvl)</span></span>
<span class="line"><span>klog_set_level_enabled(lvl, on)</span></span>
<span class="line"><span>klog_flush()</span></span>
<span class="line"><span>klog_rotate()</span></span>
<span class="line"><span>klog_filter_set(min_level)</span></span></code></pre></div><p>级别：DEBUG/INFO/WARN/ERROR/FATAL；轮转 （<code>kernel.log</code> -&gt; <code>kernel.log.1</code>，阈值 4096）和过滤是 真实存在且经过端到端验证的行为。</p>`,10)])])}const _=e(t,[["render",o]]);export{g as __pageData,_ as default};
